uint32_t __fastcall OOGUTIL_CheckCharacterLevel(uint8_t * pszLevelChars) {
    uint8_t byLevelDigit = *pszLevelChars;
    int nMaxLevelDiff = (D2IniData_multiplayer->eCTEMP_eD2PlayerStatus >> 8 & 0x1f) / 5 + 1;
    if (D2IniData_multiplayer->eCTEMP_eD2PlayerStatus & PLAYERSTATUS_Hardcore) {
      if ((int)(byLevelDigit - 0x33) <= nMaxLevelDiff && byLevelDigit >= 0x33) {
        return 0;
      }

      return 1;
    }

    return (uint32_t)((int)(byLevelDigit - 0x30) > nMaxLevelDiff);
}

// OOGMENU_AddGameToCache(pGameInfo = g_CharSelectBuffer): append one realm game to the JOIN-screen
// display cache (stride 0x3b per entry, count=nGameListDifficultyFilter). Dedups on (u16)pGameInfo[+8]=gameid.
// Copies: +8 gameid -> gwGameListCacheEntryPort; +0x14 -> gwOOGLobbyScreenState; +0x1c -> gszLanGameListEntryName;
// +0x2c -> gszLanGameListEntryDescription. Called once per incoming MCP 0x05 game packet from JoinOrCreateGame.
void __fastcall OOGMENU_AddGameToCache(int32_t pGameInfo) {
    char cChar;
    int nIndex = 0;
    if (nGameListDifficultyFilter > 0) {
      uint16_t* pwCachePort;
      pwCachePort = &gbLanGameListEntryNamePadding2[0].nJoinId;
      do {
        if (*pwCachePort == *(uint16_t*)(pGameInfo + 8)) {
          return;
        }

        nIndex++;
        pwCachePort = (uint16_t*)((int)pwCachePort + 0x3b);
      } while (nIndex < nGameListDifficultyFilter);
    }

    gbLanGameListEntryNamePadding2[nGameListDifficultyFilter].nJoinId = *(uint16_t*)(pGameInfo + 8);
    gbLanGameListEntryNamePadding2[nGameListDifficultyFilter].dwIpAddr = 0;
    gbLanGameListEntryNamePadding2[nGameListDifficultyFilter].wDisplayedCount = *(uint16_t*)(pGameInfo + 0x14);
    char* pszSrc = (char*)(pGameInfo + 0x1c);
    nIndex = nGameListDifficultyFilter * 0x3b + (intptr_t)&gbLanGameListEntryNamePadding2[0].szName - (int)pszSrc;
    do {
      cChar = *pszSrc;
      pszSrc[nIndex] = cChar;
      pszSrc++;
    } while (cChar != '\0');

    pszSrc = (char*)(pGameInfo + 0x2c);
    nIndex = nGameListDifficultyFilter * 0x3b + (intptr_t)&gbLanGameListEntryNamePadding2[0].szDescription - (int)pszSrc;
    do {
      cChar = *pszSrc;
      pszSrc[nIndex] = cChar;
      pszSrc++;
    } while (cChar != '\0');

    nGameListDifficultyFilter++;
}

void __stdcall OOGMENU_RefreshGameListDisplay() {
    uint16_t* pwEntryPort;
    uint8_t szSelectedName[256];
    char szPortText[16];
    int32_t nLastLineIndex;
    int nEntryIndex = 0;
    if (!gpOOGGameListTextBox) {
      return;
    }

    uint16_t* pwszSelectedText = D2Win::Src::D2WinTextBox::D2WINTEXTBOX_GetSelectedLineText(gpOOGGameListTextBox);
    uint32_t bHasSelection = 0;
    if (pwszSelectedText) {
      D2Lang::Unicode::UNISYS::UNICODE_WideToMultiByte((char*)szSelectedName, (uint16_t*)pwszSelectedText, 0x100);
    }

    bHasSelection = (uint32_t)(pwszSelectedText != 0);
    int32_t nScrollPos = D2Win::Src::D2WinTextBox::D2WINTEXTBOX_GetScrollPosition(gpOOGGameListTextBox);
    D2Win::Src::D2WinTextBox::D2WINTEXTBOX_ClearAllLines(gpOOGGameListTextBox);
    D2Win::Src::D2WinTextBox::D2WINTEXTBOX_ClearAllLines(gpOogGameListDetailsPanelControl);
    gnFilteredGameListCount = nGameListDifficultyFilter;
    if (!nGameListDifficultyFilter) {
      return;
    }

    int32_t bHasPeer = D2MCPClient::McpConnect::HasPeerName();
    memcpy(gbLanGameListEntryNamePadding, gbLanGameListEntryNamePadding2, nGameListDifficultyFilter * 0x3b);
    if (gnFilteredGameListCount > 0) {
      pwEntryPort = &gbLanGameListEntryNamePadding[0].wDisplayedCount;
      do {
        D2Win::Src::D2WinImage::D2WINTEXTBOX_SetTextFromAnsiSimple(gpOOGGameListTextBox, (char*)(pwEntryPort - 0x18));
        nLastLineIndex = D2Win::Src::D2WinTextBox::D2WINTEXTBOX_GetLastLineIndex(gpOOGGameListTextBox);
        if (bHasPeer) {
          _itoa((uint32_t)*pwEntryPort, szPortText, 10);
          D2Win::Src::D2WinTextBox::D2WINTEXTBOX_SetLineCellTextA(gpOOGGameListTextBox, szPortText, nLastLineIndex, 1);
        }

        nEntryIndex++;
        pwEntryPort = (uint16_t*)((int)pwEntryPort + 0x3b);
      } while (nEntryIndex < gnFilteredGameListCount);
    }
    if (bHasSelection) {
      int nCmpResult;
      nEntryIndex = 0;
      if (gnFilteredGameListCount <= 0) {
        D2Win::Src::D2WinTextBox::D2WINTEXTBOX_ScrollToLine(gpOOGGameListTextBox, nScrollPos);
        return;
      }

      do {
        nCmpResult = strcmp((char*)szSelectedName, gbLanGameListEntryNamePadding[nEntryIndex].szName);
        if (!nCmpResult) {
          D2Win::Src::D2WinTextBox::D2WINTEXTBOX_SetSelectedLine(gpOOGGameListTextBox, nEntryIndex);
          D2Win::Src::D2WinTextBox::D2WINTEXTBOX_ScrollToLine(gpOOGGameListTextBox, nScrollPos);
          return;
        }

        nEntryIndex++;
        if (nEntryIndex >= gnFilteredGameListCount) {
          D2Win::Src::D2WinTextBox::D2WINTEXTBOX_ScrollToLine(gpOOGGameListTextBox, nScrollPos);
          return;
        }
      } while (true);
    }

    D2Win::Src::D2WinTextBox::D2WINTEXTBOX_ScrollToLine(gpOOGGameListTextBox, 0);
}

