BOOL __stdcall OOGUTIL_OnPressProfileOK(D2ControlMsg * pControlMsg) {
    uint16_t* pwszLocation;
    uint16_t* pwszDescription;
    uint32_t nSendResult;
    char szDescription[204];
    char szLocation[44];
    char szSex[12];
    char* pszLastAccount;
    if (gnProfileDialogMode == 2) {
      uint16_t* pwszSex;
      pwszSex = D2Win::Src::D2WinEditBox::FORMS_TextInput_GetValue(&gpProfileEditSex->sControl);
      pwszLocation = D2Win::Src::D2WinEditBox::FORMS_TextInput_GetValue(&gpProfileEditLocation->sControl);
      pwszDescription = D2Win::Src::D2WinEditBox::FORMS_TextInput_GetValue(&gpProfileEditDescription->sControl);
      pszLastAccount = D2IniData_multiplayer->szLastBnetAccount;
      D2Lang::Unicode::UNISYS::UNICODE_WideToMultiByte(szSex, (uint16_t*)pwszSex, 8);
      D2Lang::Unicode::UNISYS::UNICODE_WideToMultiByte(szLocation, (uint16_t*)pwszLocation, 0x28);
      D2Lang::Unicode::UNISYS::UNICODE_WideToMultiByte(szDescription, (uint16_t*)pwszDescription, 200);
      nSendResult = ChatDlg::CHATDLG_SendProfileData(pszLastAccount, szSex, szLocation, szDescription);
      if (!nSendResult) {
        return 1;
      }
    }

    OOGUTIL_CloseProfileDialog();
    return 1;
}

